;; ProjectName SDK binary sources (generated by @voxgig/sdkgen).
;;
;; File content a caller hands the SDK, held as given. A string is content,
;; sent as its UTF-8 bytes: nothing here reads a path. Errors come back as
;; [code message], for the pipeline to raise in its own context.

(ns sdk.binary
  (:refer-clojure :exclude [bytes])
  (:require [voxgig.struct :as vs]
            [clojure.string :as str]))

(def RAW-BODY "$body")

(def ^:private MAXDEPTH 32)

(declare describe)

;; Not a map: a source is never read as data, copied or merged.
(deftype BinarySource [kind ^bytes data name type]
  Object
  (toString [this] (str "#sdk/binary " (vs/jsonify (describe this) (vs/jm "indent" 0)))))

(defmethod print-method BinarySource [src ^java.io.Writer w] (.write w (str src)))

(defn source? [v] (instance? BinarySource v))

(defn stream? [v] (instance? java.io.InputStream v))

(defn size [^BinarySource src] (alength ^bytes (.-data src)))

;; A source serialised anywhere is described, never copied.
(defn describe [^BinarySource src]
  (let [desc (vs/jm "binary$" "bytes" "size" (long (size src)))]
    (when (some? (.-type src)) (.put ^java.util.Map desc "type" (.-type src)))
    desc))

(defn- num-text [n]
  (cond
    (and (or (double? n) (float? n)) (== n (Math/rint (double n))) (< (Math/abs (double n)) 1e21))
    (str (long n))
    (or (double? n) (float? n)) (let [s (str n)] (if (str/ends-with? s ".0") (subs s 0 (- (count s) 2)) s))
    :else (str n)))

;; A plain value as the text of a form pair or a multipart part.
(defn item-text [v]
  (cond
    (string? v) v
    (bytes? v) (String. ^bytes v "UTF-8")
    (boolean? v) (str v)
    (number? v) (num-text v)
    (keyword? v) (name v)
    :else (vs/jsonify v (vs/jm "indent" 0))))

;; The bytes a value carries: its own, or its text's UTF-8.
(defn to-bytes ^bytes [v]
  (if (bytes? v) v (.getBytes ^String (item-text v) "UTF-8")))

(defn- opt [opts k]
  (when (instance? java.util.Map opts)
    (let [v (.get ^java.util.Map opts (keyword k))]
      (if (some? v) v (.get ^java.util.Map opts k)))))

;; The one source core builds: `data` is bytes or a string, `opts` a map
;; with name and type; an empty type is no type.
(defn bytes
  ([data] (bytes data nil))
  ([data opts]
   (let [n (opt opts "name") t (opt opts "type")]
     (BinarySource. "bytes" (to-bytes data) (when (string? n) n) (when (and (string? t) (not= "" t)) t)))))

;; The path of the first source in a value, or nil.
(defn- source-at [value path depth seen]
  (cond
    (source? value) path
    (or (nil? value) (string? value) (bytes? value) (stream? value)) nil
    (or (<= MAXDEPTH depth) (some #(identical? % value) seen)) nil
    :else
    (let [seen (conj seen value)
          pairs (cond
                  (instance? java.util.Map value)
                  (map (fn [^java.util.Map$Entry e] [(.getKey e) (.getValue e)]) (.entrySet ^java.util.Map value))
                  (or (instance? java.util.List value) (sequential? value)) (map-indexed vector value)
                  :else nil)]
      (some (fn [[k v]]
              (let [k (if (keyword? k) (name k) (str k))]
                (source-at v (if (= "" path) k (str path "." k)) (inc depth) seen)))
            pairs))))

(defn- fields-of [body]
  (let [f (vs/getprop body "fields")] (if (vs/islist f) (vec f) [])))

;; The data keys whose values are file content: a multipart or form body's
;; binary fields, and the whole of a raw body.
(defn binary-names [point]
  (let [body (vs/getprop point "body")
        kind (when (vs/ismap body) (vs/getprop body "kind"))]
    (cond
      (= "raw" kind) [RAW-BODY]
      (#{"multipart" "form"} kind)
      (vec (for [f (fields-of body)
                 :when (and (true? (vs/getprop f "binary")) (string? (vs/getprop f "name")))]
             (vs/getprop f "name")))
      :else [])))

;; Moves the values of binary fields out of the request data, before a hook,
;; a transform, validation or clean reads it. A source anywhere else is
;; refused. The context is the pipeline's atom.
(defn lift-sources! [ctx]
  (when (nil? (:sources @ctx))
    (let [names (binary-names (:point @ctx))
          reqdata (:reqdata @ctx)
          present (filterv #(and (instance? java.util.Map reqdata) (.containsKey ^java.util.Map reqdata %)) names)
          lifted (into {} (map (fn [n] [n (.get ^java.util.Map reqdata n)]) present))
          copy (if (empty? present)
                 reqdata
                 (let [out (vs/jm)]
                   (doseq [^java.util.Map$Entry e (.entrySet ^java.util.Map reqdata)]
                     (when-not (some #{(.getKey e)} present) (.put ^java.util.Map out (.getKey e) (.getValue e))))
                   out))
          stray (or (source-at copy "" 0 []) (source-at (:reqmatch @ctx) "" 0 []))]
      (if stray
        ["binary_source_refused"
         (str "A binary source was passed in \"" stray "\", which is not a field the operation declares binary.")]
        (do (swap! ctx assoc :reqdata copy :sources lifted) nil)))))

;; A response the model declares to be bytes is read only through the
;; entity's binary handle, never into its data.
(defn bytes-refused [ctx]
  (let [point (:point @ctx)
        response (vs/getprop point "response")
        transfer (some-> (:ctrl @ctx) deref :transfer)]
    (when (and (vs/ismap response) (= "raw" (vs/getprop response "kind"))
               (true? (vs/getprop response "binary")) (nil? transfer))
      (let [op (some-> (:op @ctx) deref)
            select (vs/getprop point "select")
            action (when (vs/ismap select) (vs/getprop select "$action"))]
        ["binary_sink_required"
         (str "Operation \"" (:name op) "\" on entity \"" (:entity op)
              "\" answers bytes, which never enter the entity's data: read them with "
              "(sdk.codec.handle/bytes (sdk.entity." (:entity op) "/binary entity"
              (if (nil? action) "" (str " \"" action "\"")) ")).")]))))

(defn- list-of [v]
  (cond
    (vs/islist v) (vec v)
    (and (sequential? v) (not (string? v))) (vec v)
    :else nil))

;; The values a form or multipart body carries, in wire order: the fields
;; the model declares, in its order, then any other key of the data, in code
;; point order. A list repeats its field per item, or is one value joined by
;; the field's `join`; an absent or nil value sends nothing.
(defn body-items [body data lifted]
  (let [fields (filterv #(string? (vs/getprop % "name")) (fields-of body))
        declared (mapv #(vs/getprop % "name") fields)
        plain (if (instance? java.util.Map data)
                (into {} (map (fn [^java.util.Map$Entry e] [(str (.getKey e)) (.getValue e)])
                              (.entrySet ^java.util.Map data)))
                {})
        names (concat (filter #(or (contains? plain %) (contains? lifted %)) declared)
                      (sort (remove (set declared) (keys plain))))]
    (vec
     (mapcat
      (fn [n]
        (let [field (some #(when (= n (vs/getprop % "name")) %) fields)
              value (if (contains? lifted n) (get lifted n) (get plain n))
              file (true? (vs/getprop field "binary"))
              join (vs/getprop field "join")
              item (fn [v] {:name n :field field :value v :binary file})
              items (list-of value)]
          (cond
            (nil? value) []
            (nil? items) [(item value)]
            (and (not file) (string? join))
            [(item (str/join join (map item-text (remove nil? items))))]
            :else (map item (remove nil? items)))))
      names))))
